/**************************************************************************/
/**************************************************************************/
/**                                                                       */
/** ThreadX Component                                                     */
/**                                                                       */
/**   Initialize                                                          */
/**                                                                       */
/**************************************************************************/
/**************************************************************************/

    .arch   armv8-r
    .syntax unified
    .arm

    .global _tx_thread_system_stack_ptr
    .global _tx_initialize_unused_memory

    .text
    .balign 4

/**************************************************************************/
/*                                                                        */
/*  FUNCTION                                               RELEASE        */
/*                                                                        */
/*    _tx_initialize_low_level                         Cortex-R52/GNU     */
/*                                                           6.5.2        */
/*  AUTHOR                                                                */
/*                                                                        */
/*    Frédéric Desbiens, Eclipse Foundation                               */
/*                                                                        */
/*  DESCRIPTION                                                           */
/*                                                                        */
/*    Low-level initialization for Cortex-R52 on the S32Z280-594EVB.      */
/*    Called by _tx_initialize_kernel_enter with the processor already in */
/*    Supervisor mode at EL1.                                             */
/*                                                                        */
/*    This is deliberately shorter than the A-profile reference ports:    */
/*    entry.S has already given every AArch32 mode its own stack from     */
/*    dedicated linker-script regions, so there is no stack carving to do */
/*    here and no run-time stack-overlap check to perform -- the linker   */
/*    guarantees the regions do not overlap.                              */
/*                                                                        */
/*    When built with TX_R52_USE_THREADX_IRQ, board_init() brings up the  */
/*    MPU, GICv3 and the generic timer tick here.  The MPU comes first on */
/*    this board: the GIC region has to be mapped Device nGnRnE before any*/
/*    GIC register can be touched at all.                                 */
/*    and the generic timer tick here.  That is safe this early because   */
/*    interrupts stay masked until _tx_thread_schedule enables them, so no*/
/*    tick can be delivered before the kernel is ready to take one.       */
/*    Without that symbol (the M2 cooperative demo) no tick is created,   */
/*    which keeps M2 free of any interrupt dependency.                    */
/*                                                                        */
/*  CALLED BY                                                             */
/*                                                                        */
/*    _tx_initialize_kernel_enter          ThreadX entry function         */
/*                                                                        */
/**************************************************************************/

    .global _tx_initialize_low_level
    .type   _tx_initialize_low_level, %function
_tx_initialize_low_level:

    /* Record the system stack.  The interrupt path uses it when an
       exception arrives while no thread is running.  */

    ldr     r0, =__sys_stack_top
    ldr     r1, =_tx_thread_system_stack_ptr
    str     r0, [r1]

    /* Publish the first free memory address for tx_application_define.
       _end sits above the image, .bss and every per-mode stack.  Round up
       to an 8-byte boundary so pool control blocks are aligned.  */

    ldr     r0, =_end
    add     r0, r0, #7
    bic     r0, r0, #7
    ldr     r1, =_tx_initialize_unused_memory
    str     r0, [r1]

#ifdef TX_R52_USE_THREADX_IRQ

    /* Bring up the interrupt controller and the periodic tick.  */

    push    {lr}
    bl      board_init
    pop     {lr}

#endif

    bx      lr
